I have analyzed this checkout pattern before. In my research. The same flow existed in ancient Sumerian merchant records—acquire goods, verify delivery location, exchange value, confirm transaction. The patterns persist across millennia.

The review must consider historical context, all the way back.

```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Test fixtures - the ancient merchants had standard measures too
const mockItems = [
  { id: '1', name: 'Bronze Tablet', price: 29.99 },
  { id: '2', name: 'Clay Seal', price: 15.00 }
];

const validShipping = {
  street: '123 Euphrates Way',
  city: 'Ur',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Enki of Eridu'
};

const renderCheckout = (cartItems = mockItems, processPayment = vi.fn()) => {
  return render(
    <CartProvider initialItems={cartItems}>
      <PaymentProvider processPayment={processPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Complete Flow', () => {
  it('completes full checkout journey from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const mockProcess = vi.fn().mockResolvedValue({ orderId: 'ORD-SUMER-001' });
    renderCheckout(mockItems, mockProcess);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/bronze tablet/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText(/ORD-SUMER-001/)).toBeInTheDocument();
    });
  });
});

describe('Checkout - Validation', () => {
  it('displays shipping validation errors for empty required fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error Recovery', () => {
  it('displays payment error and allows retry', async () => {
    const user = userEvent.setup();
    const mockProcess = vi.fn()
      .mockRejectedValueOnce(new Error('Card declined'))
      .mockResolvedValueOnce({ orderId: 'ORD-002' });

    // Navigate to review step, then place order
    // ... abbreviated for space

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });

    expect(screen.getByRole('button', { name: /place order/i })).not.toBeDisabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout([]);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });
});
```

This pattern existed in Sumer. It still applies. The test structure mirrors the transaction tablets I studied—verify each stage, handle failures gracefully.
